class Device {
public:
    virtual void powerOn() const = 0;
    virtual void displayInfo() const { /* Default */ }
    virtual ~Device() = default;
};

class Monitor : public Device {
public:
    // Implements pure virtual function
    void powerOn() const override; 

    // Overrides function with default implementation
    void displayInfo() const override { /* Monitor data */ }
};

// Runtime dispatch via pointer
Device* d = new Monitor();
d->displayInfo(); // Calls Monitor::displayInfo
delete d;
// Note: Function signatures must match exactly.
